<template>
  <q-dialog
    v-model="show_popup"
    position="standard"
    @keydown.esc="cleanupOnhide"
    @hide="cleanupOnhide"
  >
    <q-card class="subscription-dialog">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold text-white">{{ dynamicTitle }}</span>
        </q-toolbar-title>
        <q-btn
          flat
          round
          dense
          icon="close"
          color="white"
          @click="cleanupOnhide"
        />
      </q-toolbar>

      <q-card-section v-if="loadingPlans" class="text-center q-py-lg">
        <q-spinner size="2em" color="primary" />
      </q-card-section>

      <template v-else>
        <!-- Plan selection: show selectable plan cards -->
        <q-card-section v-if="plans.length > 0" class="plan-section">
          <div class="plan-header">{{ $t('choose_your_plan') }}</div>
          <div class="plan-grid">
            <div
              v-for="(plan, index) in plans"
              :key="plan.id"
              :class="[
                'plan-card',
                { 'plan-card--selected': !hasExistingSubscription && selectedPlan && selectedPlan.id === plan.id },
                { 'plan-card--active': isPlanActive(plan) },
                { 'plan-card--recommended': !hasExistingSubscription && isRecommended(index) && !isPlanBlocked(plan) },
                { 'plan-card--disabled': hasExistingSubscription ? !isPlanActive(plan) : isPlanBlocked(plan) },
              ]"
              @click="selectPlan(plan)"
            >
              <div v-if="isPlanActive(plan)" class="plan-badge plan-badge--active">
                {{ $t('active') || 'Active' }}
              </div>
              <div v-else-if="!hasExistingSubscription && isRecommended(index) && !isPlanBlocked(plan)" class="plan-badge">
                {{ $t('recommended') || 'Recommended' }}
              </div>
              <div class="plan-icon">
                <q-icon :name="tierIcon(index)" :size="tierIconSize(index)" />
              </div>
              <div class="plan-name">{{ plan.name }}</div>
              <div class="plan-duration">
                <q-icon name="schedule" size="14px" class="q-mr-xs" />
                {{ plan.days }} {{ $t('days') }}
              </div>
            </div>
          </div>
        </q-card-section>

        <!-- Single-plan mode: simple confirm text -->
        <q-card-section v-else>
          {{ $t('subscription_popup_info') }}
        </q-card-section>
      </template>

      <div class="row q-pb-md">
        <f-btn
          appearance="cancel"
          class="col-6 buttons"
          @click="((show_popup = false), cancelSubscription)"
        >
          {{ $t('cancel') }}
        </f-btn>
        <f-btn
          class="col-6 buttons"
          :disable="plans.length > 0 && !selectedPlan && !hasExistingSubscription"
          @click="changeSubscription"
        >
          {{ $t('confirm') }}
        </f-btn>
      </div>
    </q-card>
  </q-dialog>
</template>

<script>
import { notify } from 'src/components/notifications/notify';
import { CONSTANTS, supplier_portal_setting } from 'src/constants';
import { ApiExceptions } from 'src/exceptions';
import { isSandboxEnvironment } from 'src/pages/APIs';
import { authApiService } from 'src/services';
import { useSubscriptionStore } from 'src/store/User/subscription.store';
import {
  TIER_DEFAULTS,
  getTierKey,
  isSubscriptionForThisApp as isSubscriptionForApp,
  isPlanBlocked as isPlanBlockedPure,
  filterPlansByEnvironment,
  compareCombinedPlans,
  isAlreadySubscribedConflict,
  subscriptionMatchesApp,
} from './subscriptionDialogHelpers';

export default {
    name: 'SubscriptionDialog',
  props: {
    modelValue: {
      type: Boolean,
      required: true,
    },
    settings: {
      type: Object,
      required: true,
    },
    // App key (string) or list of app keys (array) whose plans should appear
    // in the selection list. An array mixes plans from multiple related apps
    // in a single dialog.
    appKey: {
      type: [String, Array],
      required: true,
    },
    settingType: {
      type: String,
      required: true,
    },
    // When set, plans matching this app key are auto-selected on open and
    // shown with the "recommended" badge.
    preferredAppKey: {
      type: String,
      default: '',
    },
    // When false, the dialog skips its own `createFeatureSubscription` call
    // and forwards the chosen plan to `onConfirm` for the caller to handle.
    // Used by flows that need to create multiple subs in a specific order
    // (e.g. the combined Workflow dialog: Standard first, then Advanced).
    manageCreate: {
      type: Boolean,
      default: true,
    },
    onConfirm: {
      type: Function,
      required: false,
    },
  },
  data() {
    return {
      plans: [],
      selectedPlan: null,
      loadingPlans: false,
      activePlanKeys: new Set(),
      activePlanIds: new Set(),
      hasExistingSubscription: false,
    };
  },
  computed: {
    show_popup: {
      get() {
        return this.modelValue;
      },
      set(value) {
        this.$emit('update:modelValue', value);
      },
    },

    appKeyList() {
      return Array.isArray(this.appKey) ? this.appKey : [this.appKey];
    },

    firstPreferredPlanIndex() {
      if (!this.preferredAppKey) return -1;
      return this.plans.findIndex((plan) =>
        isSubscriptionForApp(plan?.key, this.preferredAppKey),
      );
    },

    // set title based on the setting type
    dynamicTitle() {
      switch (this.settingType) {
        case 'DOCNET_SETTING':
          return this.$t('docnet_subscription');
        case 'DOC_OPERATOR_SETTING':
          return this.$t('docoperator_subscription');
        case 'OPENSEARCH_ENABLED':
          return this.$t('opensearch_subscription');
        case 'WORKFLOW_BUILDER_MODULE_SETTING':
          return this.$t('workflow_builder_subscription');
        case 'ADVANCED_WORKFLOW_MODULE_SETTING':
          return this.$t('advanced_workflow_subscription');
        case 'AGENT_MODULE_SETTING':
          return this.$t('agent_subscription');
        case CONSTANTS.DOC_SCAN_MODULE_SETTING:
          return this.$t('doc_scan_subscription') || this.$t('subscription');
        case CONSTANTS.vertex_tax_integration_setting:
          return this.$t('vertex_tax_subscription');
        case 'ANALYTICS_DASHBOARD':
          return this.$t('analytics_dashboard_subscription') || this.$t('subscription');
        case 'GROUPING_DASHBOARD':
          return this.$t('ai_warehouse_subscription');
        case 'BOD_CONNECTION_STREAM':
          return this.$t('integration_subscription');
        case supplier_portal_setting:
          return this.$t('supplier_portal_subscription');
        case 'DB_REPORTING_ENGINE':
          return this.$t('sql_bi_subscription');
        default:
          return this.$t('subscription');
      }
    },
  },
  watch: {
    show_popup(val) {
      if (val) {
        this.fetchPlans();
      } else {
        this.selectedPlan = null;
      }
    },
  },
  methods: {
    getTierInfo(plan) {
      const tier = getTierKey(plan?.key);
      return tier ? TIER_DEFAULTS[tier] : null;
    },
    isRecommended(index) {
      const plan = this.plans[index];
      if (this.preferredAppKey && plan) {
        return this.firstPreferredPlanIndex === index;
      }
      const info = this.getTierInfo(plan);
      return info ? info.recommended : index === 1;
    },
    matchesPreferredApp(plan) {
      if (!this.preferredAppKey) return false;
      return isSubscriptionForApp(plan?.key, this.preferredAppKey);
    },
    tierIcon(index) {
      const plan = this.plans[index];
      const info = this.getTierInfo(plan);
      return info ? info.icon : 'star';
    },
    tierIconSize(index) {
      const plan = this.plans[index];
      const info = this.getTierInfo(plan);
      if (info?.recommended) return '32px';
      return '28px';
    },
    async fetchPlans() {
      this.loadingPlans = true;
      this.plans = [];
      this.selectedPlan = null;
      this.activePlanKeys = new Set();
      this.activePlanIds = new Set();
      this.hasExistingSubscription = false;
      try {
        const subscriptionStore = useSubscriptionStore();
        const [allPlans] = await Promise.all([
          authApiService.getSubscriptionPlans(),
          subscriptionStore.fetchFeatureSubscriptions(),
        ]);

        // Collect plan keys and plan IDs from all active subscriptions
        for (const sub of subscriptionStore.feature_subscriptions) {
          if (sub.is_active) {
            this.activePlanIds.add(sub.plan_id);
            if (sub.plan_key) this.activePlanKeys.add(sub.plan_key);
          }
        }

        const appKeys = this.appKeyList;
        let matched = allPlans.filter((plan) =>
          appKeys.some((key) => isSubscriptionForApp(plan.key, key)),
        );
        matched = filterPlansByEnvironment(
          matched,
          isSandboxEnvironment(),
          this.activePlanKeys,
        );
        // When two app keys are mixed, group them deterministically: primary
        // entry-level plans first, then upgrade-tier plans ascending.
        if (appKeys.length >= 2) {
          matched = [...matched].sort(compareCombinedPlans(appKeys[0], appKeys[1]));
        }
        this.plans = matched;

        // Existing subscription = any ACTIVE subscription that belongs to one
        // of the dialog's app keys. Matched primarily on the SDK's
        // apps[].app_key — the same app identity the backend uses to reject a
        // duplicate — with a plan-key prefix fallback. This is the root fix for
        // the incident: a plan rename can no longer hide an active subscription
        // from the dialog and trigger a doomed create + backend conflict.
        this.hasExistingSubscription =
          subscriptionStore.feature_subscriptions.some(
            (sub) =>
              sub.is_active &&
              appKeys.some((appKey) => subscriptionMatchesApp(sub, appKey)),
          );

        // Pick a default selection: prefer plans matching `preferredAppKey`
        // when set, otherwise auto-select only when there's exactly one option.
        const available = matched.filter((p) => !this.isPlanBlocked(p));
        if (this.preferredAppKey) {
          const preferred = available.find((p) => this.matchesPreferredApp(p));
          if (preferred) this.selectedPlan = preferred;
        }
        if (!this.selectedPlan && available.length === 1) {
          this.selectedPlan = available[0];
        }
      } catch (err) {
        console.error('[SubscriptionDialog] Failed to fetch plans:', err);
        this.plans = [];
        this.selectedPlan = null;
      } finally {
        this.loadingPlans = false;
      }
    },
    isPlanActive(plan) {
      return this.activePlanIds.has(plan.id);
    },
    isSubscriptionForThisApp(planKey) {
      return this.appKeyList.some((appKey) =>
        isSubscriptionForApp(planKey, appKey),
      );
    },
    isPlanBlocked(plan) {
      // A plan is blocked when any other plan for the same app key is already
      // active. Each app key is evaluated independently — having Standard
      // active does NOT block plans of a different app key in the same list.
      for (const appKey of this.appKeyList) {
        if (!isSubscriptionForApp(plan.key, appKey)) continue;
        if (
          isPlanBlockedPure(plan, this.activePlanIds, this.activePlanKeys, appKey)
        ) {
          return true;
        }
      }
      return false;
    },
    selectPlan(plan) {
      if (!this.hasExistingSubscription && !this.isPlanBlocked(plan)) {
        this.selectedPlan = plan;
      }
    },
    cleanupOnhide() {
      this.show_popup = false;
    },
    cancelSubscription() {
      this.show_popup = false;
    },
    async changeSubscription() {
      this.show_popup = false;

      // Subscription already exists — just save the preference
      if (this.hasExistingSubscription) {
        if (this.onConfirm) {
          await this.onConfirm(true, null, this.plans);
        }
        return;
      }

      let chosenPlan = this.selectedPlan || this.plans[0];
      let planList = this.plans;

      try {
        // If plans weren't loaded (API failed on open), fetch now as fallback
        if (!chosenPlan) {
          const allPlans = await authApiService.getSubscriptionPlans();
          const appKeys = this.appKeyList;
          let matched = allPlans.filter((plan) =>
            appKeys.some((key) => isSubscriptionForApp(plan.key, key)),
          );
          matched = filterPlansByEnvironment(
            matched,
            isSandboxEnvironment(),
            this.activePlanKeys,
          );
          chosenPlan = matched[0];
          planList = matched;
          if (!chosenPlan) {
            notify.error('No subscription plan available');
            return;
          }
        }

        if (!this.manageCreate) {
          // Caller orchestrates subscription creation in their onConfirm.
          if (this.onConfirm) {
            await this.onConfirm(true, chosenPlan, planList);
          }
          return;
        }

        const subscriptionStore = useSubscriptionStore();
        const result = await subscriptionStore.createFeatureSubscription({
          plan_id: chosenPlan.id,
          start_date: new Date().toISOString(),
        });

        // Only confirm if subscription was created successfully
        if (result && this.onConfirm) {
          await this.onConfirm(true, chosenPlan, planList);
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err);
        // The backend matches subscriptions by APP; this dialog detects an
        // existing subscription by plan-key prefix. When the org already has
        // an active subscription using THIS module's app via a plan whose key
        // the prefix map doesn't recognise (e.g. a bundle, or a plan renamed
        // by a price-list realignment), createFeatureSubscription fails with
        // "Organisation already has an active subscription using <app>".
        // Because the create was for this module's own app, that conflict
        // means the org IS already subscribed — so enable the module (sync the
        // setting to the existing subscription) instead of leaving it stuck
        // with the toggle off and no way to re-enable it.
        if (isAlreadySubscribedConflict(err) || isAlreadySubscribedConflict(msg)) {
          if (this.onConfirm) {
            await this.onConfirm(true, chosenPlan, planList);
          }
          return;
        }
        notify.error(msg);
      } finally {
        this.loading = false;
      }
    },
  },
};
</script>

